// HasDeployTasks applies the HasEdge predicate on the "deploy_tasks" edge.
func HasDeployTasks() predicate.ChangeOrder {
	return predicate.ChangeOrder(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.O2M, false, DeployTasksTable, DeployTasksColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasDeployTasksWith applies the HasEdge predicate on the "deploy_tasks" edge with a given conditions (other predicates).
func HasDeployTasksWith(preds ...predicate.DeployTask) predicate.ChangeOrder {
	return predicate.ChangeOrder(func(s *sql.Selector) {
		step := newDeployTasksStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// And groups predicates with the AND operator between them.
func And(predicates ...predicate.ChangeOrder) predicate.ChangeOrder {
	return predicate.ChangeOrder(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.ChangeOrder) predicate.ChangeOrder {
	return predicate.ChangeOrder(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.ChangeOrder) predicate.ChangeOrder {
	return predicate.ChangeOrder(sql.NotPredicates(p))
}
